// emitEndpointEvents emits endpoint events of the given type to the xDS control
// plane for every endpoint found in the namespace. Endpoints are discovered via
// the CiliumEndpointSlice resource when CiliumEndpointSlice mode is enabled, and
// via the CiliumEndpoint resource otherwise.
func (ops *EnrollmentReconciler) emitEndpointEvents(ctx context.Context, namespace string, eventType xds.EndpointEventType) {
	if ops.endpointEventCh == nil {
		return
	}

	eps, err := ops.namespaceEndpoints(ctx, namespace)
	if err != nil {
		ops.logger.Error("Failed to list endpoints for namespace",
			logfields.K8sNamespace, namespace,
			logfields.Error, err,
		)
		return
	}

	for _, ep := range eps {
		select {
		case ops.endpointEventCh <- &xds.EndpointEvent{Type: eventType, CiliumEndpoint: ep}:
		case <-ctx.Done():
			return
		}
	}
}

// namespaceEndpoints returns the CiliumEndpoints in the given namespace,
// sourced from either the CiliumEndpointSlice or CiliumEndpoint resource
// depending on whether CiliumEndpointSlice mode is enabled.
func (ops *EnrollmentReconciler) namespaceEndpoints(ctx context.Context, namespace string) ([]*types.CiliumEndpoint, error) {
	var eps []*types.CiliumEndpoint

	if option.Config.EnableCiliumEndpointSlice {
		if ops.ciliumEndpointSliceResource == nil {
			return nil, nil
		}
		store, err := ops.ciliumEndpointSliceResource.Store(ctx)
		if err != nil {
			return nil, fmt.Errorf("failed to get CiliumEndpointSlice store: %w", err)
		}
		for _, ces := range store.List() {
			if ces.Namespace != namespace {
				continue
			}
			for i := range ces.Endpoints {
				eps = append(eps, k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&ces.Endpoints[i], ces.Namespace))
			}
		}
		return eps, nil
	}

	if ops.ciliumEndpointResource == nil {
		return nil, nil
	}
	store, err := ops.ciliumEndpointResource.Store(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get CiliumEndpoint store: %w", err)
	}
	for _, cep := range store.List() {
		if cep.Namespace != namespace {
			continue
		}
		eps = append(eps, cep)
	}
	return eps, nil
